package com.digitalhealth.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="notifications",indexes=@Index(name="idx_notification_worker_created",columnList="worker_id,created_at")) public class Notification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="worker_id",nullable=false) private Worker worker; @Column(nullable=false) private String message; @Column(nullable=false) private String type="SYSTEM"; @Column(nullable=false) private boolean readStatus=false; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public Worker getWorker(){return worker;} public void setWorker(Worker x){worker=x;} public String getMessage(){return message;} public void setMessage(String x){message=x;} public String getType(){return type;} public void setType(String x){type=x;} public boolean isReadStatus(){return readStatus;} public void setReadStatus(boolean x){readStatus=x;} public LocalDateTime getCreatedAt(){return createdAt;} }
